"""Short actual-foot measurements; residuals are reported, not hidden by broad gates."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/locomotion';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1000});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready&&INK.Locomotion');p.locator('.kinetic-launch button').click()
 p.evaluate('''()=>{window.gaitMeasure=(id,scenario)=>{const A=SVG_FIGHTER,G=A.state,L=INK.Locomotion;A.start(id,'ryu','training','classic',33);G.paused=true;document.getElementById('dummy').value='idle';A.teleport(0,scenario==='wall'?1320:400);A.teleport(1,scenario==='wall'?200:1100);A.step();const f=A.fighters[0],rows=[],checks=[];let prev=null,frame=0;
 const button=(key,on)=>{G.paused=false;(on?A.press:A.release)(0,key);G.paused=true;};
 const capture=label=>{const pose=A.visualPose(f),rig=INK.Runtime.visualRig(f,pose),world={x:f.x,y:665+f.y,scale:f.renderScale||f.ch.scale||1,facing:f.dir},sample=L.sample(f,f._inkVisualClock),feet=Object.fromEntries(['front','rear'].map(k=>[k,INK.Rig.world(pose,INK.Runtime.socket(pose,rig,k+'Foot'),world)]));for(const k of ['front','rear']){const handoff=f._inkSupport?.handoff?.feet[k],target=sample?(handoff?handoff.map((v,j)=>v+(sample.feet[k][j]-v)*sample.blend):sample.feet[k]):handoff,jump=prev?Math.hypot(feet[k][0]-prev[k][0],feet[k][1]-prev[k][1]):0;rows.push({frame,label,foot:k,state:f.state,x:f.x,actual:feet[k],target:target||null,blend:sample?.blend??0,kind:sample?(sample.weights[k]>.8?'support':'swing'):'none',residual:target?Math.hypot(feet[k][0]-target[0],feet[k][1]-target[1]):null,jump});}prev=feet;frame++;};
 const step=(n,label)=>{for(let i=0;i<n;i++){A.step();capture(label);}};
 if(scenario==='idle'){step(15,'idle');checks.push({name:'idle Juri does not acquire gait',passed:!f._inkLocomotion});}
 else if(scenario==='dash'){button('right',true);A.step();button('right',false);A.step();button('right',true);step(27,'dash-stop');button('right',false);step(18,'settle');}
 else {button('right',true);step(24,'walk');button('right',false);step(17,'stop');if(scenario==='walk'){button('left',true);step(24,'reverse');button('left',false);step(17,'settle');}}
 if(scenario==='walk'){button('right',true);step(6,'restart');const state=JSON.stringify(A.combatState()),targets=JSON.stringify(L.sample(f,f._inkVisualClock));for(let i=0;i<12;i++)A.renderFraction(i%3/2);checks.push({name:'paused render preserves state and foot targets',passed:state===JSON.stringify(A.combatState())&&targets===JSON.stringify(L.sample(f,f._inkVisualClock))});button('right',false);for(const move of ['sMP','sHK']){G.paused=false;const ok=A.tryMove(0,move);G.paused=true;A.step();checks.push({name:move+' immediately releases gait',passed:ok&&!!f.attack&&!f._inkLocomotion});step(45,move);}}
 const full=rows.filter(r=>r.target&&r.blend>.999),max=(list,key)=>list.length?Math.max(...list.map(r=>r[key])):0,summary={id,scenario,samples:rows.length,residualScope:'fullBlend uses gait target; unload uses frozen handoff/gait blend',unloadResidual:max(rows.filter(r=>r.target&&r.blend<.999),'residual'),fullBlendResidual:max(full,'residual'),handoffJump:max(rows.filter(r=>['stop','settle'].includes(r.label)),'jump'),supportResidual:max(full.filter(r=>r.kind==='support'),'residual'),swingResidual:max(full.filter(r=>r.kind==='swing'),'residual'),maxJump:max(rows,'jump'),gaitJump:max(rows.filter(r=>!['sMP','sHK'].includes(r.label)),'jump'),attackJump:max(rows.filter(r=>['sMP','sHK'].includes(r.label)),'jump'),worstResidual:full.sort((a,b)=>b.residual-a.residual).slice(0,3),worstJump:rows.filter(r=>!['sMP','sHK'].includes(r.label)).sort((a,b)=>b.jump-a.jump).slice(0,3),checks,finite:rows.every(r=>r.actual.every(Number.isFinite)&&Number.isFinite(r.jump))};return summary;};}''')
 runs=[]
 for id in ['ryu','ken','chun','cammy','luke','juri','mai','iori']:runs.append(p.evaluate('id=>gaitMeasure(id,"walk")',id))
 for id,scenario in [('ryu','dash'),('cammy','wall'),('juri','idle')]:runs.append(p.evaluate('([id,s])=>gaitMeasure(id,s)',[id,scenario]))
 for id in ['ryu','cammy']:
  p.evaluate('''id=>{const A=SVG_FIGHTER,G=A.state;A.start(id,'ryu','training','classic',33);G.paused=false;document.getElementById('dummy').value='idle';A.teleport(0,400);A.teleport(1,1100);A.press(0,'right');G.paused=true;A.step(24);G.paused=false;A.release(0,'right');G.paused=true;A.step(3);A.renderFraction(1);}''',id);p.locator('#game').screenshot(path=str(O/(id+'-walk-stop.png')))
 b.close()
report={'htmlSha256':hashlib.sha256(html).hexdigest(),'runs':runs,'errors':errors,'note':'Residual/jump values are measurements, not a visual-quality acceptance threshold.'};(O/'playable.json').write_text(json.dumps(report,indent=2)+'\n')
for r in runs:print(r['id'],r['scenario'],'support',round(r['supportResidual'],3),'swing',round(r['swingResidual'],3),'gaitJump',round(r['gaitJump'],3),'handoff',round(r['handoffJump'],3),'contracts',all(c['passed'] for c in r['checks']))
assert not errors and all(r['finite'] and all(c['passed'] for c in r['checks']) for r in runs),errors
